export interface ParsedDkimKey {
  valid: boolean;
  version?: string;
  keyType: string; // rsa | ed25519
  publicKey: string;
  revoked: boolean;
  testing: boolean;
  hashAlgs?: string[];
  serviceTypes?: string[];
  keyBits: number | null;
  errors: string[];
  warnings: string[];
}

function readLength(bytes: Uint8Array, pos: number): [len: number, next: number] {
  const first = bytes[pos]!;
  if (first < 0x80) return [first, pos + 1];
  const n = first & 0x7f;
  let len = 0;
  for (let i = 0; i < n; i++) len = (len << 8) | bytes[pos + 1 + i]!;
  return [len, pos + 1 + n];
}

interface Der {
  tag: number;
  start: number; // content start
  len: number;
  end: number;
}

function readDer(bytes: Uint8Array, pos: number): Der {
  const tag = bytes[pos]!;
  const [len, start] = readLength(bytes, pos + 1);
  return { tag, start, len, end: start + len };
}

function base64ToBytes(b64: string): Uint8Array {
  const clean = b64.replace(/\s+/g, '');
  const bin = atob(clean);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** RSA modulus size in bits from an SPKI or PKCS#1 DER public key (base64). */
export function rsaKeyBits(b64: string): number | null {
  try {
    const bytes = base64ToBytes(b64);
    let seq = readDer(bytes, 0);
    if (seq.tag !== 0x30) return null;
    let first = readDer(bytes, seq.start);
    if (first.tag === 0x30) {
      // SPKI: AlgorithmIdentifier, then BIT STRING containing RSAPublicKey
      const bit = readDer(bytes, first.end);
      if (bit.tag !== 0x03) return null;
      seq = readDer(bytes, bit.start + 1); // skip unused-bits byte
      if (seq.tag !== 0x30) return null;
      first = readDer(bytes, seq.start);
    }
    if (first.tag !== 0x02) return null;
    let start = first.start;
    let len = first.len;
    while (len > 0 && bytes[start] === 0) {
      start++;
      len--;
    }
    if (len === 0) return 0;
    const lead = bytes[start]!;
    return (len - 1) * 8 + (32 - Math.clz32(lead));
  } catch {
    return null;
  }
}

export function parseDkimKey(record: string): ParsedDkimKey {
  const errors: string[] = [];
  const warnings: string[] = [];
  const tags: Record<string, string> = {};
  for (const part of record.split(';')) {
    const eq = part.indexOf('=');
    if (eq < 0) {
      if (part.trim()) errors.push(`Malformed tag "${part.trim()}".`);
      continue;
    }
    tags[part.slice(0, eq).trim().toLowerCase()] = part.slice(eq + 1).trim();
  }
  if (tags.v !== undefined && tags.v !== 'DKIM1') errors.push('v= must be "DKIM1".');
  const keyType = (tags.k ?? 'rsa').toLowerCase();
  if (keyType !== 'rsa' && keyType !== 'ed25519') errors.push(`Unknown key type k=${keyType}.`);
  const publicKey = (tags.p ?? '').replace(/\s+/g, '');
  if (tags.p === undefined) errors.push('Missing public key (p=).');
  const revoked = tags.p !== undefined && publicKey === '';
  const flags = (tags.t ?? '').split(':').map((f) => f.trim());
  const testing = flags.includes('y');
  let keyBits: number | null = null;
  if (!revoked && publicKey) {
    if (!/^[A-Za-z0-9+/]+=*$/.test(publicKey)) errors.push('Public key is not valid base64.');
    else if (keyType === 'ed25519') keyBits = 256;
    else {
      keyBits = rsaKeyBits(publicKey);
      if (keyBits === null) errors.push('Public key could not be decoded as an RSA key.');
      else if (keyBits < 1024) errors.push(`RSA key is only ${keyBits} bits. Gmail rejects keys under 1024 bits; use 2048.`);
      else if (keyBits < 2048) warnings.push(`RSA key is ${keyBits} bits. 2048 bits is recommended.`);
    }
  }
  if (revoked) warnings.push('Key is revoked (empty p=). Mail signed with this selector fails DKIM.');
  if (testing) warnings.push('t=y (testing) is set: some receivers treat DKIM failures as passes. Remove it when done testing.');
  return {
    valid: errors.length === 0,
    ...(tags.v ? { version: tags.v } : {}),
    keyType,
    publicKey,
    revoked,
    testing,
    ...(tags.h ? { hashAlgs: tags.h.split(':') } : {}),
    ...(tags.s ? { serviceTypes: tags.s.split(':') } : {}),
    keyBits,
    errors,
    warnings,
  };
}

export interface DkimSelectorResult {
  selector: string;
  host: string;
  record: string;
  cnameTarget?: string;
  parsed: ParsedDkimKey;
}

export interface DkimAnalysis {
  domain: string;
  status: 'ok' | 'missing' | 'invalid' | 'error';
  selectors: DkimSelectorResult[];
  probed: number;
  errors: string[];
  warnings: string[];
}

export async function lookupDkimSelector(domain: string, selector: string, resolver: Resolver): Promise<DkimSelectorResult | null> {
  const host = `${selector}._domainkey.${domain}`;
  const r = await resolver.query(host, 'TXT');
  const rec = r.answers.map((a) => a.data).find((d) => /(^|;)\s*(v=DKIM1|k=|p=)/i.test(d));
  if (!rec) return null;
  return { selector, host, record: rec, ...(r.cnameTarget ? { cnameTarget: r.cnameTarget } : {}), parsed: parseDkimKey(rec) };
}

export async function analyzeDkim(domain: string, resolver: Resolver, extraSelectors: string[] = []): Promise<DkimAnalysis> {
  const selectors = [...new Set([...extraSelectors.map((s) => s.toLowerCase().trim()).filter(Boolean), ...COMMON_DKIM_SELECTORS])];
  const results = await Promise.all(selectors.map((s) => lookupDkimSelector(domain, s, resolver).catch(() => null)));
  const found = results.filter((r): r is DkimSelectorResult => r !== null);
  const errors: string[] = [];
  const warnings: string[] = [];
  for (const f of found) {
    errors.push(...f.parsed.errors.map((e) => `${f.selector}: ${e}`));
    warnings.push(...f.parsed.warnings.map((w) => `${f.selector}: ${w}`));
  }
  if (found.length === 0) {
    // Distinguish "nothing exists" from a DNS outage using the base domain.
    const probe = await resolveTxt(resolver, domain);
    if (probe.status === 'ERROR' || probe.status === 'SERVFAIL') {
      return { domain, status: 'error', selectors: [], probed: selectors.length, errors: ['DNS lookup failed.'], warnings };
    }
    return {
      domain,
      status: 'missing',
      selectors: [],
      probed: selectors.length,
      errors: ['No DKIM key found on common selectors. If you use a custom selector, enter it to check it.'],
      warnings,
    };
  }
  const active = found.filter((f) => !f.parsed.revoked);
  const status = active.some((f) => f.parsed.valid) ? (errors.length ? 'invalid' : 'ok') : 'invalid';
  return { domain, status, selectors: found, probed: selectors.length, errors, warnings };
}
